"""Finalize immutable source/test pins after the real extracted C chains pass."""
import argparse,pathlib,json,hashlib
p=argparse.ArgumentParser();p.add_argument('source',type=pathlib.Path);p.add_argument('baseline',type=pathlib.Path);a=p.parse_args();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();m=json.loads((a.source/'source-manifest.json').read_text());assert sha(a.baseline/'source-manifest.json')==m['baseline_manifest_sha256'];before={p.name:sha(p)for p in(a.baseline/'driver').iterdir()if p.is_file()};after={p.name:sha(p)for p in(a.source/'driver').iterdir()if p.is_file()};assert before==m['before'] and after==m['after'];assert sha(a.source/'ownership-gates.patch')==m['patch_sha256'];r=json.loads((a.source/'response-tests.json').read_text());w=json.loads((a.source/'wrapper-tests.json').read_text());assert r['passed'] and w['passed'];tools=pathlib.Path(__file__).resolve().parent
