(a.source/'source-manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');summary={'source':str(a.source),'manifest_sha256':sha(a.source/'source-manifest.json'),'patch_sha256':sha(a.source/'ownership-gates.patch'),'header_sha256':m['header_sha256'],'baseline_unchanged':True,'changed_files':m['changed_files'],'response_workdir':r['workdir'],'wrapper_workdir':w['workdir']};print(json.dumps(summary,ensure_ascii=False,indent=2))
